```js
const { Program, quit, key, style } = require('bare-tui')
const updater = require('bare-tui-updater')
const { wire } = require('bare-tui-updater/pear')

const pear = new PearRuntime({ ... })

class App {
  constructor() {
    this.upd = updater.create({
      mode: 'confirm',
      border: false,      // single line instead of a box
      position: 'bottom', // or 'top'
      align: 'right',     // or 'left' (default) / 'center'
      onAccept: async () => {
        await pear.updater.applyUpdate()
      }
    })
  }
  update(msg) {
    if (key.matches(msg, 'ctrl+c')) return [this, quit]
    const [u, cmd] = this.upd.update(msg)
    this.upd = u
    return [this, cmd]
  }
  view() {
    // Costs zero rows while idle; the banner appears only when there's an update.
    return this.upd.layout('My app...')
  }
}

const program = new Program(new App())
wire(this.upd, { updater: pear.updater, send: program.send.bind(program) })
program.run()
```

**The widget does not restart the process automatically.** After applying an update, it displays "restart to use it" and the user/shell is responsible for relaunching the CLI.

This is intentional: there is no cross-platform restart primitive in `pear-runtime`, and safe restart logic depends heavily on whether the app is a standalone `bare-build` binary (re-exec `Bare.argv[0]`) or running from source (`bare bin.js`, cannot safely restart itself). The decision is yours.

A simple re-exec pattern (for standalone binaries):

```js
const { spawn } = require('bare-subprocess')

async function restart() {
  const child = spawn(Bare.argv[0], Bare.argv.slice(1), {
    detached: true,
    stdio: 'inherit'
  })
  child.unref()
  await new Promise((r) => setImmediate(r))
  Bare.exit(0)
}
```

Wire this into your app's menu or call it after `onAccept` if you want automatic restart. See [examples/pear.js](./examples/pear.js) for a complete integration.

usage:
Given an entry module `core.js` that exports a `start` function receiving the IPC stream and an optional `ready` callback. The function may optionally return (or resolve to) a function that runs before the bundle exits:

```js
module.exports = async function start(ipc, ready) {
  ipc.on('data', (data) => {
    // Handle messages from the host.
  })

  // Optionally call `ready()` to signal readiness early. Otherwise it is
  // signaled automatically when `start()` resolves.
  ready()

  return async function stop() {
    // Clean up before the bundle exits.
  }
}
```

The `ipc` argument is a duplex byte stream. Anything written to it is delivered to the host, and `'data'` events fire when the host writes back.

Stow it for the `bare-sidecar` target:

```js
const stow = require('bare-stow')

const entry = new URL('file:///app/core.js')
const out = new URL('file:///app/out/index.js')

for await (const artifact of stow(entry, 'bare-sidecar', out)) {
  console.log(artifact.url.href)
}
```

Or equivalently from the command line:

```console
$ bare-stow --target bare-sidecar --out ./out/index.js ./core.js
```

This writes the harness to `out` and the bundle alongside it. The harness can then be required from the host and booted with `start()`. The harness awaits the worker's `ready` signal before resolving, so by the time `start()` returns the bundle is up:

```js
const harness = require('/app/out/index.js')

const { ipc } = await harness.start()

ipc.write(Buffer.from('hello from the host'))

ipc.on('exit', (code) => {
  console.log('bundle exited with', code)
})

// Request a graceful shutdown.
ipc.destroy()
```

